// Builds requests/<id>.json for scripts/agent/space-watch.ts. The id is GENERATED here and never taken from the caller, so it cannot be a path. Text is only data; nothing here executes it.
const b = $input.first().json.body ?? {};
const text = String(b.text ?? b.message ?? '').trim().slice(0, 4000);
if (!text) throw new Error('empty request');
const from = String(b.from ?? b.email ?? b.name ?? 'unknown').slice(0, 200);
const attachments = Array.isArray(b.attachments) ? b.attachments.filter((a) => typeof a === 'string' && /^[\w.\- ]{1,100}$/.test(a)) : [];
const id = 'req-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
const at = new Date().toISOString();
const body = JSON.stringify({ id, from, text, attachments, at }, null, 2);
const binary = { data: await this.helpers.prepareBinaryData(Buffer.from(body, 'utf8'), id + '.json', 'application/json') };
return [{ json: { id, ok: true }, binary }];
